insert into public.font_pairs(title,description,heading_font,body_font,translations) select 'Assinatura do clube','Use o script só em destaques curtos: nomes, chamadas e assinaturas.','Amoresa','Work Sans','{"pt": {"title": "Assinatura do clube", "description": "Use o script só em destaques curtos: nomes, chamadas e assinaturas."}, "en": {"title": "Club signature", "description": "Use script for short highlights: names, calls to action and signatures."}, "fr": {"title": "Signature du club", "description": "Utilisez la police manuscrite pour les noms, appels et signatures."}, "es": {"title": "Firma del club", "description": "Usa la fuente manuscrita para nombres, llamadas y firmas."}}'::jsonb where not exists(select 1 from public.font_pairs where title='Assinatura do clube');
insert into public.font_pairs(title,description,heading_font,body_font,translations) select 'Editorial elegante','Serifada nos títulos e sans no corpo — uma combinação versátil para carrosséis.','Operetta / Playfair Display','Work Sans','{"pt": {"title": "Editorial elegante", "description": "Serifada nos títulos e sans no corpo — uma combinação versátil para carrosséis."}, "en": {"title": "Elegant editorial", "description": "Serif headings and sans-serif body text: a versatile pairing for carousels."}, "fr": {"title": "Éditorial élégant", "description": "Titres à empattements et texte sans empattement : une association polyvalente pour les carrousels."}, "es": {"title": "Editorial elegante", "description": "Títulos con serifas y texto sin serifas: una combinación versátil para carruseles."}}'::jsonb where not exists(select 1 from public.font_pairs where title='Editorial elegante');
insert into public.font_pairs(title,description,heading_font,body_font,translations) select 'Direto ao ponto','Para conteúdos didáticos, listas e posts com muita informação.','Work Sans Bold','Work Sans Light','{"pt": {"title": "Direto ao ponto", "description": "Para conteúdos didáticos, listas e posts com muita informação."}, "en": {"title": "Straight to the point", "description": "For educational content, lists and information-rich posts."}, "fr": {"title": "Droit au but", "description": "Pour les contenus pédagogiques, listes et publications riches en informations."}, "es": {"title": "Directo al grano", "description": "Para contenido educativo, listas y publicaciones con mucha información."}}'::jsonb where not exists(select 1 from public.font_pairs where title='Direto ao ponto');